import re

def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("Invalid input")
    if not re.match(r'^(\d+[hms])+$', s):
        raise ValueError("Invalid duration format")
    total = 0
    for value, unit in re.findall(r'(\d+)([hms])', s):
        v = int(value)
        if unit == 'h':
            total += v * 3600
        elif unit == 'm':
            total += v * 60
        elif unit == 's':
            total += v
    return total
